package org.jsoup.nodes;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.jsoup.helper.Validate;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class XmlDeclaration_getWholeDeclaration_TriageGen1Test {







    @Test
    public void test_xml_with_no_version_or_encoding_return_xml() {
        XmlDeclaration xmlDeclaration = new XmlDeclaration("xml", null, false);
        assertNull(xmlDeclaration.attributes.get("version"));
        assertNull(xmlDeclaration.attributes.get("encoding"));
        String result = xmlDeclaration.getWholeDeclaration();
        assertEquals("xml", result);
    }










}

